From 94cac8bbac612df5a925357c00af079280f5d934 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 19 Nov 2026 15:18:30 +0100
Subject: [PATCH] suspendsession: Fall back to plain sleep if the sleep mode is
 unavailable

With "Standby, then hibernate" or "Hybrid sleep" set but no longer possible, for
example after hibernation was disabled, the lid, power button and Sleep key did
nothing. Use plain sleep in that case instead.

BUG: 500841
BUG: 498298
---
 daemon/actions/bundled/suspendsession.cpp | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/daemon/actions/bundled/suspendsession.cpp b/daemon/actions/bundled/suspendsession.cpp
index 3106ae267..f9110d35a 100644
--- a/daemon/actions/bundled/suspendsession.cpp
+++ b/daemon/actions/bundled/suspendsession.cpp
@@ -99,9 +99,9 @@ void SuspendSession::triggerImpl(const QVariantMap &args)
         Q_EMIT aboutToSuspend();
         auto sleepMode = args.contains(u"SleepMode"_s) ? static_cast<PowerDevil::SleepMode>(args[u"SleepMode"_s].toUInt()) : m_sleepMode;

-        if (sleepMode == PowerDevil::SleepMode::SuspendThenHibernate) {
+        if (sleepMode == PowerDevil::SleepMode::SuspendThenHibernate && core()->suspendController()->canSuspendThenHibernate()) {
             core()->suspendController()->suspendThenHibernate();
-        } else if (sleepMode == PowerDevil::SleepMode::HybridSuspend) {
+        } else if (sleepMode == PowerDevil::SleepMode::HybridSuspend && core()->suspendController()->canHybridSuspend()) {
             core()->suspendController()->hybridSuspend();
         } else {
             core()->suspendController()->suspend();
-- 
